props.default:
forwardRef<HTMLTableSectionElement, CTableHeadProps>(
  ({ children, className, color, ...rest }, ref) => {
    return (
      <thead
        className={
          classNames(
            {
              [`table-${color}`]: color,
            },
            className
          ) || undefined
        }
        {...rest}
        ref={ref}
      >
        {children}
      </thead>
    )
  }
)
